INSERT INTO academic_attempts(id,student_id,subject_id,term_id,assessment_model,attendance_percentage) SELECT md5('current:'||ss.student_id::text||ss.subject_id::text)::uuid,ss.student_id,ss.subject_id,'2026.2',COALESCE(am.model_type,'AV_SERIES'),ss.current_attendance_percentage FROM student_subjects ss LEFT JOIN assessment_models am ON am.subject_id=ss.subject_id ON CONFLICT DO NOTHING;
INSERT INTO student_grades(id,student_id,subject_id,attempt_id,assessment_name,grade_value) SELECT md5(a.id::text||n.name)::uuid,a.student_id,a.subject_id,a.id,n.name,NULL FROM academic_attempts a CROSS JOIN (VALUES ('AV1'),('AV2'),('AV3'),('NOTA_UNICA')) n(name) WHERE (a.assessment_model='AV_SERIES' AND n.name<>'NOTA_UNICA') OR (a.assessment_model='SINGLE_GRADE' AND n.name='NOTA_UNICA') ON CONFLICT(attempt_id,assessment_name) DO NOTHING;
