UPDATE student_grades g SET attempt_id=a.id FROM academic_attempts a WHERE a.student_id=g.student_id AND a.subject_id=g.subject_id AND a.term_id='2026.2' AND g.attempt_id IS NULL;


UPDATE student_grades g SET grade_value=CASE WHEN g.assessment_name='AV1' THEN 6 WHEN g.assessment_name='AV2' THEN 7 ELSE NULL END FROM academic_attempts a WHERE g.attempt_id=a.id AND g.grade_value IS NULL AND a.assessment_model='AV_SERIES' AND g.assessment_name IN ('AV1','AV2') AND a.subject_id NOT IN ('8f5c7eb3-e2b4-4eff-a1b0-0e9f10000002');







UPDATE subject_offerings o SET teacher=s.teacher FROM subjects s WHERE s.id=o.subject_id;


